impl RpcResponse {
    pub const MSG_ID: u16 = SF_SYSTEM_RPC_RESPONSE_MSG_ID;
    pub const MAX_SIZE: usize = SF_SYSTEM_RPC_RESPONSE_MAX_SIZE;
    pub const SIZE: usize = SF_SYSTEM_RPC_RESPONSE_MAX_SIZE;
    pub const BASE_SIZE: usize = SF_SYSTEM_RPC_RESPONSE_BASE_SIZE;
    pub const MAGIC1: u8 = SF_SYSTEM_RPC_RESPONSE_MAGIC1;
    pub const MAGIC2: u8 = SF_SYSTEM_RPC_RESPONSE_MAGIC2;
    pub const IS_VARIABLE: bool = false;

    /// Serialize the message into a byte buffer. Returns bytes written.
    pub fn pack(&self, buf: &mut [u8]) -> usize {
        let mut _pos = 0usize;
        buf[_pos.._pos+2].copy_from_slice(&self.call_id.to_le_bytes());
        _pos += 2;
        buf[_pos.._pos+2].copy_from_slice(&self.payload_id.to_le_bytes());
        _pos += 2;
        buf[_pos] = self.payload_magic1;
        _pos += 1;
        buf[_pos] = self.payload_magic2;
        _pos += 1;
        buf[_pos] = self.status;
        _pos += 1;
        _pos
    }

    /// Serialize the message to exactly MAX_SIZE bytes (fixed-size encoding).
    /// Use this for profiles without a length field (sensor, ipc).
    pub fn pack_max_size(&self, buf: &mut [u8]) -> usize {
        let mut _pos = 0usize;
        buf[_pos.._pos+2].copy_from_slice(&self.call_id.to_le_bytes());
        _pos += 2;
        buf[_pos.._pos+2].copy_from_slice(&self.payload_id.to_le_bytes());
        _pos += 2;
        buf[_pos] = self.payload_magic1;
        _pos += 1;
        buf[_pos] = self.payload_magic2;
        _pos += 1;
        buf[_pos] = self.status;
        _pos += 1;
        _pos
    }

    /// Deserialize a message from a byte buffer. Returns None if buffer is too small.
    pub fn unpack(buf: &[u8]) -> Option<Self> {
        let mut _padded = [0u8; Self::SIZE];
        let _n = buf.len().min(Self::SIZE);
        _padded[.._n].copy_from_slice(&buf[.._n]);
        let buf = &_padded[..];
        let mut _pos = 0usize;
        #[allow(unused_variables)]
        let _ = _pos;
        let call_id = u16::from_le_bytes(buf.get(_pos.._pos+2)?.try_into().ok()?);
        _pos += 2;
        let payload_id = u16::from_le_bytes(buf.get(_pos.._pos+2)?.try_into().ok()?);
        _pos += 2;
        let payload_magic1 = *buf.get(_pos)?;
        _pos += 1;
        let payload_magic2 = *buf.get(_pos)?;
        _pos += 1;
        let status = *buf.get(_pos)?;
        _pos += 1;
        Some(Self {
            call_id,
            payload_id,
            payload_magic1,
            payload_magic2,
            status,
        })
    }

    /// Get message info (size + magic numbers) for frame parsing.
    pub fn message_info() -> crate::frame_base::MessageInfo {
        crate::frame_base::MessageInfo::new_with_base_size(Self::MAX_SIZE, Self::MAGIC1, Self::MAGIC2, Self::BASE_SIZE)
    }

    /// Reset every field to its schema default.
    pub fn reset(&mut self) { *self = Self::default(); }

    /// True when this message encodes exactly like one at its schema defaults.
    pub fn is_default(&self) -> bool { Self::same_encoding_(self, &Self::default()) }

    /// True when field `call_id` holds its schema default.
    pub fn call_id_is_default(&self) -> bool {
        let mut probe = Self::default();
        probe.call_id = self.call_id.clone();
        Self::same_encoding_(&probe, &Self::default())
    }

    /// True when field `payload_id` holds its schema default.
    pub fn payload_id_is_default(&self) -> bool {
        let mut probe = Self::default();
        probe.payload_id = self.payload_id.clone();
        Self::same_encoding_(&probe, &Self::default())
    }

    /// True when field `payload_magic1` holds its schema default.
    pub fn payload_magic1_is_default(&self) -> bool {
        let mut probe = Self::default();
        probe.payload_magic1 = self.payload_magic1.clone();
        Self::same_encoding_(&probe, &Self::default())
    }

    /// True when field `payload_magic2` holds its schema default.
    pub fn payload_magic2_is_default(&self) -> bool {
        let mut probe = Self::default();
        probe.payload_magic2 = self.payload_magic2.clone();
        Self::same_encoding_(&probe, &Self::default())
    }

    /// True when field `status` holds its schema default.
    pub fn status_is_default(&self) -> bool {
        let mut probe = Self::default();
        probe.status = self.status.clone();
        Self::same_encoding_(&probe, &Self::default())
    }

    fn same_encoding_(a: &Self, b: &Self) -> bool {
        let mut x = [0u8; Self::SIZE + 1];
        let mut y = [0u8; Self::SIZE + 1];
        let nx = a.pack(&mut x);
        let ny = b.pack(&mut y);
        x[..nx] == y[..ny]
    }
}

impl crate::frame_base::StructFrameMessage for RpcResponse {
    const MSG_ID: u16 = SF_SYSTEM_RPC_RESPONSE_MSG_ID;
    const MAX_SIZE: usize = SF_SYSTEM_RPC_RESPONSE_MAX_SIZE;
    const MAGIC1: u8 = SF_SYSTEM_RPC_RESPONSE_MAGIC1;
    const MAGIC2: u8 = SF_SYSTEM_RPC_RESPONSE_MAGIC2;
    const IS_VARIABLE: bool = false;
    fn pack(&self, buf: &mut [u8]) -> usize { Self::pack(self, buf) }
    fn pack_max_size(&self, buf: &mut [u8]) -> usize { Self::pack_max_size(self, buf) }
    fn unpack(buf: &[u8]) -> Option<Self> { Self::unpack(buf) }
}

// ============================================================================
// Message info lookup
// ============================================================================

/// Look up message info (size + magic bytes) by message ID.
pub fn get_message_info(msg_id: u16) -> Option<MessageInfo> {
    match msg_id {
        1 => Some(Heartbeat::message_info()),
        2 => Some(LinkStats::message_info()),
        33 => Some(LinkTestAck::message_info()),
        34 => Some(LinkTestData::message_info()),
        36 => Some(LinkTestReport::message_info()),
        32 => Some(LinkTestStart::message_info()),
        35 => Some(LinkTestStop::message_info()),
        16 => Some(Ping::message_info()),
        17 => Some(Pong::message_info()),
        48 => Some(RpcRequest::message_info()),
        49 => Some(RpcResponse::message_info()),
        _ => None,
    }
}
